import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/SAVE.md","filePath":"manual-en/SAVE.md","lastUpdated":1785684581000}'),n={name:"manual-en/SAVE.md"};function i(d,e,c,r,l,m){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h3 id="_9-6-save" tabindex="-1">9.6 SAVE <a class="header-anchor" href="#_9-6-save" aria-label="Permalink to &quot;9.6 SAVE&quot;">​</a></h3><pre><code>SAVE
        /OUTFILE={’file_name’,file_handle}
        /UNSELECTED={RETAIN,DELETE}
        /{UNCOMPRESSED,COMPRESSED,ZCOMPRESSED}
        /PERMISSIONS={WRITEABLE,READONLY}
        /DROP=var_list
        /KEEP=var_list
        /VERSION=version
        /RENAME=(src_names=target_names)…
        /NAMES
        /MAP
</code></pre><p>The <code>SAVE</code> procedure causes the dictionary and data in the active dataset to be written to a system file.</p><p>OUTFILE is the only required subcommand. Specify the system file to be written as a string file name or a file handle (see <a href="./File-Handles">File Handles</a>).</p><p>By default, cases excluded with FILTER are written to the system file. These can be excluded by specifying <code>DELETE</code> on the <code>UNSELECTED</code> subcommand. Specifying <code>RETAIN</code> makes the default explicit.</p><p>The <code>UNCOMPRESSED</code>, <code>COMPRESSED</code>, and <code>ZCOMPRESSED</code> subcommand determine the system file’s compression level:</p><p><code>UNCOMPRESSED</code></p><p>Data is not compressed. Each numeric value uses 8 bytes of disk space. Each string value uses one byte per column width, rounded up to a multiple of 8 bytes.</p><p><code>COMPRESSED</code></p><p>Data is compressed with a simple algorithm. Each integer numeric value between -99 and 151, inclusive, or system missing value uses one byte of disk space. Each 8-byte segment of a string that consists only of spaces uses 1 byte. Any other numeric value or 8-byte string segment uses 9 bytes of disk space.</p><p><code>ZCOMPRESSED</code></p><p>Data is compressed with the “deflate” compression algorithm specified in RFC 1951 (the same algorithm used by <code>gzip</code>). Files written with this compression level cannot be read by PSPP 0.8.1 or earlier or by SPSS 20 or earlier.</p><p><code>COMPRESSED</code> is the default compression level. The SET command (see <a href="./SET">SET</a>) can change this default.</p><p>The <code>PERMISSIONS</code> subcommand specifies permissions for the new system file. WRITEABLE, the default, creates the file with read and write permission. READONLY creates the file for read-only access.</p><p>By default, all the variables in the active dataset dictionary are written to the system file. The <code>DROP</code> subcommand can be used to specify a list of variables not to be written. In contrast, KEEP specifies variables to be written, with all variables not specified not written.</p><p>Normally variables are saved to a system file under the same names they have in the active dataset. Use the <code>RENAME</code> subcommand to change these names. Specify, within parentheses, a list of variable names followed by an equals sign (‘=’) and the names that they should be renamed to. Multiple parenthesized groups of variable names can be included on a single <code>RENAME</code> subcommand. Variables’ names may be swapped using a <code>RENAME</code> subcommand of the form <code>/RENAME=(A B=B A)</code>.</p><p>Alternate syntax for the <code>RENAME</code> subcommand allows the parentheses to be eliminated. When this is done, only a single variable may be renamed at once. For instance, <code>/RENAME=A=B</code>. This alternate syntax is deprecated.</p><p><code>DROP</code>, <code>KEEP</code>, and <code>RENAME</code> are performed in left-to-right order. They each may be present any number of times. <code>SAVE</code> never modifies the active dataset. <code>DROP</code>, <code>KEEP</code>, and <code>RENAME</code> only affect the system file written to disk.</p><p>The <code>VERSION</code> subcommand specifies the version of the file format. Valid versions are 2 and 3. The default version is 3. In version 2 system files, variable names longer than 8 bytes are truncated. The two versions are otherwise identical.</p><p>The <code>NAMES</code> and <code>MAP</code> subcommands are currently ignored.</p><p><code>SAVE</code> causes the data to be read. It is a procedure.</p>`,21)])])}const h=a(n,[["render",i]]);export{p as __pageData,h as default};
